from sage.all_cmdline import *   # import sage library

_sage_const_75 = Integer(75); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_40 = Integer(40); _sage_const_36 = Integer(36); _sage_const_24 = Integer(24); _sage_const_8 = Integer(8); _sage_const_16 = Integer(16)
def protocolo_ingenieria_inversa(coeffs, escala_S, nombre):
    print(f"\n{'='*_sage_const_75 }")
    print(f"VALIDANDO PROTOCOLO: {nombre}")
    print(f"{'='*_sage_const_75 }")
    
    # 1. Definición de la Curva base
    E = EllipticCurve(coeffs)
    R = QQ['n']; (n,) = R._first_ngens(1)
    f_poly = E.hyperelliptic_polynomials()[_sage_const_0 ]
    f_n = R(f_poly.list())
    
    # 2. Reconstrucción del Operador-Área Adaptativo
    # Aplicamos un factor de escala S que permite la sintonía fina
    # Dn = (f(n) - constante) / S
    constante = f_n.constant_coefficient()
    Dn = (f_n - constante) / escala_S
    
    print(f"[PASO 1] Operador Área derivado: Dn = {Dn}")
    
    # 3. Análisis de Núcleo Oblongo (Tu Teoría)
    nucleo = n*(n-_sage_const_1 )
    cociente, residuo = Dn.quo_rem(nucleo)
    
    print("-" * _sage_const_40 )
    if residuo == _sage_const_0 :
        print(f"[!] ÉXITO: Núcleo Oblongo n(n-1) detectado con cociente: {cociente}")
        print(f"    La curva {nombre} es estructuralmente compatible con tu preprint.")
    else:
        print(f"[?] Residuo detectado: {residuo}")
        print(f"    Se requiere ajuste de fase d-paramétrica.")
    print("-" * _sage_const_40 )

    # 4. Validación de Puntos Ancla (Búsqueda de soluciones enteras)
    print(f"[PASO 2] Localizando Nodos de la Red (Puntos Ancla)...")
    try:
        pts = E.integral_points()
        for p in pts:
            n_val, y_val = p[_sage_const_0 ], abs(p[_sage_const_1 ])
            # Si el área es Dn, buscamos j tal que Dn = 2j(j-1)
            # Esto implica que f(n) debe estar relacionado con (4j-2)^2
            if n_val > _sage_const_1 :
                print(f"    > Nodo de Red encontrado: n={n_val}, y={y_val}")
    except:
        print("    Búsqueda limitada por el modelo de la curva.")

# --- EJECUCIÓN CON CURVAS QUE SÍ CUMPLEN EL PROTOCOLO ---

# Caso A: Curva de Congruentes Clásica (y^2 = x^3 - n^2*x)
